cmd:
set -u
LOG=$(pmset -g log 2>/dev/null) || { echo "BLIND: cannot read pmset -g log"; exit 2; }
CUS=$(pmset -g custom 2>/dev/null) || { echo "BLIND: cannot read pmset -g custom"; exit 2; }
[ -n "$LOG" ] || { echo "BLIND: pmset -g log returned nothing"; exit 2; }
AC=$(printf '%s\n' "$CUS" | sed -n '/^AC Power/,$p' | awk '$1=="sleep"{print $2; exit}')
case "$AC" in ''|*[!0-9]*) echo "BLIND: could not parse the AC sleep setting"; exit 2;; esac
CUT=$(date -v-24H '+%Y-%m-%d %H:%M:%S') || { echo "BLIND: date -v unavailable"; exit 2; }
N=$(printf '%s\n' "$LOG" | grep 'Entering Sleep state' | awk -v c="$CUT" '$1" "$2 > c' | wc -l | tr -d ' ')
PWR=$(pmset -g batt 2>/dev/null | head -1)
F=0
[ "$AC" -eq 0 ] || { echo "FAIL: pmset AC sleep=$AC, must be 0. Fix: sudo pmset -c sleep 0 disksleep 0 standby 0 powernap 0"; F=1; }
[ "$N" -eq 0 ] || { echo "FAIL: the substrate slept $N times in the last 24h (pmset -g log)"; F=1; }
case "$PWR" in *"'AC Power'"*) ;; *) echo "FAIL: on battery, not AC. Under R14 this laptop is production and it is on a countdown."; F=1;; esac
[ "$F" -eq 0 ] && echo "PASS: AC sleep=0, on AC power, 0 sleeps in 24h"
exit $F
